<?php
function mk($m=PDO::ERRMODE_EXCEPTION){ $d=new PDO('sqlite::memory:',null,null,[PDO::ATTR_ERRMODE=>$m]); $d->exec("create table t(id integer, name text, f real, n text, b blob); insert into t values(1,'a',1.5,null,'bl'),(2,'bb',2.5,'x','zz')"); return $d;}
function t($l,$f){ echo "-- $l\n"; try{ $f(); }catch(Throwable $e){ echo get_class($e),': ',$e->getMessage(),"\n"; } }
$d=mk();
t('idx+name',function() use($d){ $s=$d->prepare('select id,name,f,n from t order by id'); var_dump($s->bindColumn(1,$a)); var_dump($s->bindColumn('name',$b)); $s->bindColumn(3,$c); $s->bindColumn(4,$e); $s->execute();
 while($r=$s->fetch(PDO::FETCH_BOUND)){ var_dump($r); var_dump($a,$b,$c,$e);} var_dump($s->fetch(PDO::FETCH_BOUND)); var_dump($a); });
t('types',function() use($d){ $s=$d->prepare('select id,name,f,n,id from t order by id'); $s->bindColumn(1,$a,PDO::PARAM_STR);$s->bindColumn(2,$b,PDO::PARAM_INT);$s->bindColumn(3,$c,PDO::PARAM_INT);$s->bindColumn(4,$e,PDO::PARAM_NULL);$s->bindColumn(5,$g,PDO::PARAM_BOOL);$s->execute();
 while($s->fetch(PDO::FETCH_BOUND)) { var_dump($a,$b,$c,$e,$g);} });
t('lob',function() use($d){ $s=$d->prepare('select b, name from t'); $s->bindColumn(1,$a,PDO::PARAM_LOB);$s->bindColumn(2,$b,PDO::PARAM_LOB);$s->execute(); $s->fetch(PDO::FETCH_BOUND); var_dump(is_resource($a), stream_get_contents($a), stream_get_contents($b)); });
t('maxlen',function() use($d){ $s=$d->prepare('select id,name from t'); var_dump($s->bindColumn(1,$a,PDO::PARAM_INT,10,null)); $s->bindColumn(2,$b,PDO::PARAM_STR,1,'x'); $s->execute(); $s->fetch(PDO::FETCH_BOUND); var_dump($a,$b); });
t('rebind',function() use($d){ $s=$d->prepare('select id,name from t'); $s->bindColumn(1,$a);$s->bindColumn(1,$b); $s->execute(); $s->fetch(PDO::FETCH_BOUND); var_dump(isset($a),$b);});
t('nonexist name',function() use($d){ $s=$d->prepare('select id from t'); var_dump($s->bindColumn('zzz',$a)); $s->execute(); var_dump($s->fetch(PDO::FETCH_BOUND)); print_r($s->errorInfo()); });
t('nonexist idx',function() use($d){ $s=$d->prepare('select id from t'); var_dump($s->bindColumn(5,$a)); var_dump($s->bindColumn(0,$a)); $s->execute(); var_dump($s->fetch(PDO::FETCH_BOUND)); print_r($s->errorInfo()); });
t('after exec',function() use($d){ $s=$d->prepare('select id,name from t order by id'); $s->execute(); var_dump($s->bindColumn(1,$a)); var_dump($s->bindColumn('name',$b)); var_dump($s->fetch(PDO::FETCH_BOUND)); var_dump($a,$b); });
t('reexec',function() use($d){ $s=$d->prepare('select id from t order by id'); $s->bindColumn(1,$a); $s->execute(); $s->fetch(PDO::FETCH_BOUND); echo $a,"\n"; $s->execute(); $s->fetch(PDO::FETCH_BOUND); echo $a,"\n";$s->closeCursor(); $a='k'; $s->execute(); $s->fetch(PDO::FETCH_BOUND); echo $a,"\n";});
t('fetchAll bound',function() use($d){ $s=$d->prepare('select id from t order by id'); $s->bindColumn(1,$a); $s->execute(); var_dump($s->fetchAll(PDO::FETCH_BOUND)); var_dump($a); });
t('foreach',function() use($d){ $s=$d->prepare('select id,name from t order by id'); $s->bindColumn(1,$a);$s->bindColumn(2,$b); $s->setFetchMode(PDO::FETCH_BOUND); $s->execute(); foreach($s as $k=>$r){ var_dump($k,$r,$a,$b);} });
t('query setFetchMode',function() use($d){ $s=$d->query('select id,name from t'); $s->bindColumn(1,$a); $s->setFetchMode(PDO::FETCH_BOUND); foreach($s as $r) var_dump($r,$a); });
t('no bound',function() use($d){ $s=$d->prepare('select id from t order by id');  $s->execute(); var_dump($s->fetch(PDO::FETCH_BOUND)); var_dump($s->fetch(PDO::FETCH_BOUND)); var_dump($s->fetch(PDO::FETCH_BOUND));});
t('stringify',function() use($d){ $d->setAttribute(PDO::ATTR_STRINGIFY_FETCHES,true); $s=$d->prepare('select id,f,n from t order by id'); $s->bindColumn(1,$a);$s->bindColumn(2,$b);$s->bindColumn(3,$c); $s->execute(); $s->fetch(PDO::FETCH_BOUND); var_dump($a,$b,$c); $d->setAttribute(PDO::ATTR_STRINGIFY_FETCHES,false);});
t('oracle',function() use($d){ $d->setAttribute(PDO::ATTR_ORACLE_NULLS,PDO::NULL_TO_STRING); $s=$d->prepare('select n from t order by id'); $s->bindColumn(1,$a); $s->execute(); $s->fetch(PDO::FETCH_BOUND); var_dump($a); $d->setAttribute(PDO::ATTR_ORACLE_NULLS,PDO::NULL_NATURAL);});
t('case',function() use($d){ $d->setAttribute(PDO::ATTR_CASE,PDO::CASE_UPPER); $s=$d->prepare('select id,name from t order by id'); var_dump($s->bindColumn('NAME',$a)); var_dump($s->bindColumn('name',$b)); $s->execute(); $s->fetch(PDO::FETCH_BOUND); var_dump($a,$b); $d->setAttribute(PDO::ATTR_CASE,PDO::CASE_NATURAL);});
t('zero cols',function() use($d){ $s=$d->prepare('create table z(a)'); var_dump($s->bindColumn(1,$a)); $s->execute(); var_dump($s->fetch(PDO::FETCH_BOUND)); });
t('flags',function() use($d){ $s=$d->prepare('select id,name from t order by id'); $s->bindColumn(1,$a); $s->execute(); var_dump($s->fetch(PDO::FETCH_BOUND|PDO::FETCH_GROUP)); var_dump($a);});
t('fetchColumn/other modes keep bound',function() use($d){ $s=$d->prepare('select id,name from t order by id'); $s->bindColumn(1,$a); $s->execute(); var_dump($s->fetch(PDO::FETCH_ASSOC)); var_dump($a); var_dump($s->fetchColumn(1)); var_dump($a);$s->execute(); var_dump($s->fetch(PDO::FETCH_NUM)); var_dump($a);});
t('ostr/ int conv',function() use($d){ $s=$d->prepare("select 'abc', 3, 4.7, '12'"); $s->bindColumn(1,$a,PDO::PARAM_INT);$s->bindColumn(2,$b,PDO::PARAM_STR);$s->bindColumn(3,$c,PDO::PARAM_STR);$s->bindColumn(4,$e,PDO::PARAM_INT); $s->execute(); $s->fetch(PDO::FETCH_BOUND); var_dump($a,$b,$c,$e);});
t('bind type invalid',function() use($d){ $s=$d->prepare("select 1"); var_dump($s->bindColumn(1,$a,99)); $s->execute(); $s->fetch(PDO::FETCH_BOUND); var_dump($a);});
t('bind name unknown silent',function(){ $d=mk(PDO::ERRMODE_SILENT); $s=$d->prepare('select id from t'); var_dump($s->bindColumn('zzz',$a)); print_r($s->errorInfo()); $s->execute(); var_dump($s->fetch(PDO::FETCH_BOUND)); });
t('bind name unknown warn',function(){ set_error_handler(function($n,$s){echo "W: $s\n";return true;}); $d=mk(PDO::ERRMODE_WARNING); $s=$d->prepare('select id from t'); var_dump($s->bindColumn('zzz',$a)); print_r($s->errorInfo()); $s->execute(); var_dump($s->fetch(PDO::FETCH_BOUND)); restore_error_handler();});
t('bind idx 0 silent',function(){ $d=mk(PDO::ERRMODE_SILENT); $s=$d->prepare('select id from t'); var_dump($s->bindColumn(0,$a)); print_r($s->errorInfo());  });
t('invalid index at fetch',function() use($d){ foreach ([5, 'zzz'] as $c) { $s=$d->prepare('select 1 as a'); $s->bindColumn($c,$x); var_dump($s->execute()); try { var_dump($s->fetch(PDO::FETCH_BOUND)); } catch (ValueError $e) { echo $e->getMessage(), "\n"; } var_dump($s->fetch(PDO::FETCH_BOUND)); } $s=$d->prepare('select 1 as a'); $s->bindColumn(5,$x); $s->execute(); try { $s->fetchAll(PDO::FETCH_COLUMN); } catch (ValueError $e) { echo $e->getMessage(), "\n"; } });
